import { loop, pattern, step } from 'strudel';

const kick = pattern([step.on, step.off, step.on, step.off]);
const hiHats = pattern([step.on, step.off, step.on, step.off]);

const bassline = pattern([step.note('C4'), step.note('Eb4'), step.note('G4'), step.note('Bb4')]);

const stab = pattern([step.note('C5'), step.note('Eb5'), step.note('G5'), step.note('Bb5')]);

loop({ length: 4, repeat: 8 }, () => [
  kick(),
  hiHats(),
  bassline(),
  stab()
]);

