  const kick = strudel.oscillator({ type: 'square', frequency: 110, gain: 0.5 });
  const hiHats = strudel.oscillator({ type: 'triangle', frequency: 350, gain: 0.3, envelope: { attack: 0.01, decay: 0.1 } });
  const bass = strudel.oscillator({ type: 'sine', frequency: 30, gain: 0.5, envelope: { attack: 0.1, decay: 1 } });
  const lead = strudel.oscillator({ type: 'sawtooth', frequency: 220, gain: 0.3, envelope: { attack: 0.01, decay: 0.5 } });

  strudel.play({
    beats: [
      [kick, hiHats, bass, lead],
      [kick, hiHats, bass],
      [kick, hiHats, bass, lead],
      [kick, hiHats, bass]
    ],
    loop: true
  });
};

