const melody = new PatternBuilder()
  .withSteps([Note.C5, Note.E5, Note.G5, Note.Bb5])
  .repeat(4);

const loop = new Pattern()
  .withTrack(kick)
  .withTrack(hiHats)
  .withTrack(bassline)
  .withTrack(melody);

loop.setTempo(tempo);
